::v-deep .el-input__suffix {
  line-height: 40px
}

::v-deep .el-input__inner {
  cursor: pointer;
}

::v-deep .el-tree-node > .el-tree-node__children {
  width: 100%;
}

.xt_tree_select {
  position: relative;

  .tree_box {
    width: 100%;
    min-width: 320px;
    position: absolute;
    background: #fff;
    border-radius: 4px;
    z-index: 999;
    top: 50px;
    transition: height 0.3s;
  }

  .show_tree {
    height: 250px;
    border: 1px solid #E4E7ED;
    box-shadow: 0 2px 12px 0 rgba(0, 0, 0, .1);

    .popper__arrow {
      position: absolute;
      top: -6px;
      left: 35px;
      margin-right: 3px;
      border-width: 6px;
      filter: drop-shadow(0 2px 12px rgba(0, 0, 0, .03));
      display: block;
      width: 0;
      height: 0;
      border-color: transparent;
      border-style: solid;
      border-top-width: 0;
      border-bottom-color: #EBEEF5;

      &::after {
        content: " ";
        border-width: 6px;
        position: absolute;
        display: block;
        width: 0;
        height: 0;
        border-color: transparent;
        border-style: solid;
        top: 2px;
        margin-left: -6px;
        border-top-width: 0;
        border-bottom-color: #FFF;
      }
    }
  }

  .hide_tree {
    height: 0px;
  }
}
